python3 - <<'PY'
import re
lines = open('/tmp/trace-run.yaml', errors='replace').readlines()
# 提取 trace 事件 + test 块结构
events = []
entries = []  # (line_no, test_name)
for i, l in enumerate(lines):
    if l.startswith("- test:"):
        entries.append((i, l.strip()))
    m = re.search(r"TRACE T(\d+) (snap: sum=(\d+) gen=(\d+) wd=(\d+)|RESET \(rd=(\d+)\)|retry: gen0=(\d+) gen=(\d+) wd=(\d+))", l)
    if m:
        t = int(m.group(1))
        if "snap" in l:
            events.append((i, t, "snap", int(m.group(3)), int(m.group(4)), int(m.group(5))))
        elif "RESET" in l:
            events.append((i, t, "reset", None, None, int(m.group(6))))
        else:
            events.append((i, t, "retry", None, int(m.group(7)), int(m.group(9))))
print("test 条目:", [(n, s.split()[2] if len(s.split())>2 else s) for n, s in entries[:8]])
print("trace 事件数:", len(events), " retry 事件:", sum(1 for e in events if e[2]=='retry'))
# 找 sum=0 的 snap（失败形态的前兆）与其前后文
for idx, e in enumerate(events):
    if e[2] == "snap" and e[3] == 0:
        print("\n=== 首个 sum=0 snap @line", e[0]+1, "===")
        for x in events[max(0,idx-6):idx+6]:
            print(f"  line {x[0]+1}: T{x[1]} {x[2]} sum={x[3]} gen={x[4]} wd={x[5]}")
        break
else:
    print("无 sum=0 snap")
# gen 序列按线程轨迹异常检测: 同线程 gen 回退
last_gen = {}
for e in events:
    if e[2] in ("snap","retry") and e[4] is not None:
        t = e[1]
        if t in last_gen and e[4] < last_gen[t]:
            print(f"线程 T{t} gen 回退 {last_gen[t]}→{e[4]} @line {e[0]+1}"); break
        last_gen[t] = e[4]
